    98	                        let tail = self.0.tail_start.into_usize();
    99	                        let tail_len = self.0.tail_len.into_usize();
   100	                        if tail != start {
   101	                            let dst = source_vec.as_mut_ptr().add(start);
   102	                            let src = source_vec.as_ptr().add(tail);
   103	                            ptr::copy(src, dst, tail_len);
