    let mut min = BinaryHeap::<i32, Min, 8>::new();
    for x in [9, 7, 8, 3, 5, 6] { max.push(x).unwrap(); min.push(x).unwrap(); }
    { let mut root = max.peek_mut().unwrap(); *root = 0; }
    { let mut root = min.peek_mut().unwrap(); *root = 10; }
